BOOL converter_gui_open(struct converter_gui *gui)
{
    if (!gui->win) gui->win = (struct Window *)IIntuition->IDoMethod(gui->window, WM_OPEN);
    return gui->win != NULL;
}

void converter_gui_close(struct converter_gui *gui)
{
    if (gui->win) IIntuition->IDoMethod(gui->window, WM_CLOSE);
    gui->win = NULL;
}

void converter_gui_dispose(struct converter_gui *gui)
{
    converter_gui_close(gui);
    if (gui->window) IIntuition->DisposeObject(gui->window);
    gui->window = NULL;
}

uint32 converter_gui_signal(struct converter_gui *gui)
{
    uint32 sig = 0;
    if (gui->window) IIntuition->GetAttr(WINDOW_SigMask, gui->window, &sig);
    return sig;
}

/* A gadget reported an event: id is which (CONVERTER_...), code depends on the gadget. */
static void converter_gadget_event(struct converter_gui *gui, uint32 id, uint16 code)
{
    (void)code;
    switch (id) {
    case CONVERTER_CELSIUS:
        /* USER-BEGIN CONVERTER_CELSIUS */
        convert(gui);   /* Return in the Celsius field converts too */
        /* USER-END CONVERTER_CELSIUS */
        break;
    case CONVERTER_CONVERT:
        /* USER-BEGIN CONVERTER_CONVERT */
        convert(gui);
        /* USER-END CONVERTER_CONVERT */
        break;
    case CONVERTER_FAHRENHEIT:
        /* USER-BEGIN CONVERTER_FAHRENHEIT */
        /* Return was pressed. The text:
           STRPTR text = NULL;
           IIntuition->GetAttr(STRINGA_TextVal, gui->obj[CONVERTER_FAHRENHEIT], (uint32 *)&text); */
        /* USER-END CONVERTER_FAHRENHEIT */
        break;
    default:
        break;
    }
}

BOOL converter_gui_handle(struct converter_gui *gui)
{
    uint32 result;
    uint16 code = 0;
    while ((result = IIntuition->IDoMethod(gui->window, WM_HANDLEINPUT, &code)) != WMHI_LASTMSG) {
        switch (result & WMHI_CLASSMASK) {
        case WMHI_CLOSEWINDOW:
            /* USER-BEGIN close */
            gui->quit = TRUE;
            /* USER-END close */
            break;
        case WMHI_GADGETUP:
            converter_gadget_event(gui, result & WMHI_GADGETMASK, code);
            break;
        }
    }
    return !gui->quit;
}
